-- 006: Configurable drinks, table service, private guest tracking, and stock-aware recipes.
-- OrderStockDeduction remains the only stock deduction point. It runs from the locked
-- payment RPC in 004, so unpaid orders do not consume stock and payment + deduction roll back together.
begin;

create table if not exists public."DiningTable" (
  "DiningTableID" bigint generated by default as identity primary key,
  "TableNumber" text not null unique check (length(trim("TableNumber")) between 1 and 40),
  "PublicToken" uuid not null default gen_random_uuid() unique,
  "IsActive" boolean not null default true,
  "CreatedAt" timestamptz not null default now(),
  "UpdatedAt" timestamptz not null default now()
);

alter table public."Order"
  add column if not exists "ServiceType" text,
  add column if not exists "DiningTableID" bigint references public."DiningTable"("DiningTableID") on delete restrict;
alter table public."Order" drop constraint if exists order_service_type_check;
alter table public."Order" add constraint order_service_type_check
  check ("ServiceType" is null or "ServiceType" in ('dine_in', 'takeaway'));
create index if not exists order_dining_table_idx on public."Order" ("DiningTableID", "OrderDate" desc) where "DiningTableID" is not null;

create table if not exists public."MenuCustomizationGroup" (
  "CustomizationGroupID" bigint generated by default as identity primary key,
  "MenuItemID" bigint not null references public."MenuItems"("ItemID") on delete cascade,
  "Name" text not null,
  "SelectionType" text not null default 'single' check ("SelectionType" in ('single', 'multiple')),
  "IsRequired" boolean not null default false,
  "MinSelections" integer not null default 0 check ("MinSelections" >= 0),
  "MaxSelections" integer not null default 1 check ("MaxSelections" >= 1),
  "SortOrder" integer not null default 0,
  "IsActive" boolean not null default true,
  check ("MinSelections" <= "MaxSelections"),
  check (not "IsRequired" or "MinSelections" >= 1),
  unique ("MenuItemID", "Name")
);
create index if not exists menu_customization_group_item_idx on public."MenuCustomizationGroup" ("MenuItemID", "SortOrder");

create table if not exists public."MenuCustomizationOption" (
  "CustomizationOptionID" bigint generated by default as identity primary key,
  "CustomizationGroupID" bigint not null references public."MenuCustomizationGroup"("CustomizationGroupID") on delete cascade,
  "Name" text not null,
  "PriceDelta" numeric(12,2) not null default 0,
  "IngredientMultiplier" numeric(8,4) not null default 1 check ("IngredientMultiplier" > 0),
  "IsDefault" boolean not null default false,
  "SortOrder" integer not null default 0,
  "IsActive" boolean not null default true,
  unique ("CustomizationGroupID", "Name")
);
create unique index if not exists menu_customization_one_default_idx on public."MenuCustomizationOption" ("CustomizationGroupID") where "IsDefault";
create index if not exists menu_customization_option_group_idx on public."MenuCustomizationOption" ("CustomizationGroupID", "SortOrder");

create table if not exists public."MenuOptionIngredient" (
  "CustomizationOptionID" bigint not null references public."MenuCustomizationOption"("CustomizationOptionID") on delete cascade,
  "InventoryItemID" bigint not null references public."InventoryItem"("InventoryItemID") on delete restrict,
  "QuantityRequired" numeric(14,3) not null check ("QuantityRequired" > 0),
  "ReplacesInventoryItemID" bigint references public."InventoryItem"("InventoryItemID") on delete restrict,
  "ScaleWithSize" boolean not null default false,
  primary key ("CustomizationOptionID", "InventoryItemID"),
  check ("ReplacesInventoryItemID" is null or "ReplacesInventoryItemID" <> "InventoryItemID")
);
create index if not exists menu_option_ingredient_inventory_idx on public."MenuOptionIngredient" ("InventoryItemID");

-- A pair of groups is unrestricted until the admin adds it here. Restricted pairs
-- must be explicitly listed in MenuCustomizationAllowedPair.
create table if not exists public."MenuCustomizationGroupPair" (
  "GroupAID" bigint not null references public."MenuCustomizationGroup"("CustomizationGroupID") on delete cascade,
  "GroupBID" bigint not null references public."MenuCustomizationGroup"("CustomizationGroupID") on delete cascade,
  primary key ("GroupAID", "GroupBID"),
  check ("GroupAID" < "GroupBID")
);
create table if not exists public."MenuCustomizationAllowedPair" (
  "OptionAID" bigint not null references public."MenuCustomizationOption"("CustomizationOptionID") on delete cascade,
  "OptionBID" bigint not null references public."MenuCustomizationOption"("CustomizationOptionID") on delete cascade,
  primary key ("OptionAID", "OptionBID"),
  check ("OptionAID" < "OptionBID")
);

alter table public."OrderItem"
  add column if not exists "SelectedOptionIDs" bigint[] not null default '{}'::bigint[],
  add column if not exists "OptionsSnapshot" jsonb not null default '[]'::jsonb;

-- Guest QR tokens grant access to a single order only. The raw token is never stored.
create table if not exists public."GuestOrderAccess" (
  "OrderID" bigint primary key references public."Order"("OrderID") on delete cascade,
  "TokenHash" text not null unique,
  "CreatedAt" timestamptz not null default now()
);

alter table public."DiningTable" enable row level security;
alter table public."MenuCustomizationGroup" enable row level security;
alter table public."MenuCustomizationOption" enable row level security;
alter table public."MenuOptionIngredient" enable row level security;
alter table public."MenuCustomizationGroupPair" enable row level security;
alter table public."MenuCustomizationAllowedPair" enable row level security;
alter table public."GuestOrderAccess" enable row level security;
revoke all on public."DiningTable", public."MenuCustomizationGroup", public."MenuCustomizationOption",
  public."MenuOptionIngredient", public."MenuCustomizationGroupPair", public."MenuCustomizationAllowedPair",
  public."GuestOrderAccess" from public, anon, authenticated;

create or replace function public.esmiringkape_selected_customization(p_menu_item_id bigint, p_selected_option_ids bigint[])
returns jsonb
language plpgsql stable security definer
set search_path = pg_catalog, public
as $$
declare
  v_ids bigint[] := coalesce(p_selected_option_ids, '{}'::bigint[]);
  v_group record;
  v_count integer;
  v_price numeric(12,2);
  v_options jsonb;
begin
  if cardinality(v_ids) <> (select count(distinct selected.option_id) from unnest(v_ids) as selected(option_id)) then
    raise exception 'A customization option was selected more than once' using errcode = '22023';
  end if;
  if exists (
    select 1 from unnest(v_ids) as selected(option_id)
    left join public."MenuCustomizationOption" o on o."CustomizationOptionID" = selected.option_id and o."IsActive"
    left join public."MenuCustomizationGroup" g on g."CustomizationGroupID" = o."CustomizationGroupID" and g."MenuItemID" = p_menu_item_id and g."IsActive"
    where o."CustomizationOptionID" is null or g."CustomizationGroupID" is null
  ) then raise exception 'One or more selected options are no longer available. Refresh the menu.' using errcode = '23514'; end if;

  for v_group in
    select g."CustomizationGroupID", g."Name", g."SelectionType", g."IsRequired", g."MinSelections", g."MaxSelections"
    from public."MenuCustomizationGroup" g where g."MenuItemID" = p_menu_item_id and g."IsActive"
  loop
    select count(*) into v_count
    from public."MenuCustomizationOption" o
    where o."CustomizationGroupID" = v_group."CustomizationGroupID" and o."IsActive"
      and o."CustomizationOptionID" = any(v_ids);
    if v_count < v_group."MinSelections" or v_count > v_group."MaxSelections"
       or (v_group."SelectionType" = 'single' and v_count > 1) then
      raise exception 'Choose % to % option(s) for %', v_group."MinSelections", v_group."MaxSelections", v_group."Name" using errcode = '22023';
    end if;
  end loop;

  if exists (
    select 1
    from unnest(v_ids) as ids_a(option_id)
    join public."MenuCustomizationOption" a on a."CustomizationOptionID" = ids_a.option_id
    join public."MenuCustomizationGroup" ag on ag."CustomizationGroupID" = a."CustomizationGroupID"
    join unnest(v_ids) as ids_b(option_id) on ids_b.option_id > ids_a.option_id
    join public."MenuCustomizationOption" b on b."CustomizationOptionID" = ids_b.option_id
    join public."MenuCustomizationGroup" bg on bg."CustomizationGroupID" = b."CustomizationGroupID"
    join public."MenuCustomizationGroupPair" gp on gp."GroupAID" = least(ag."CustomizationGroupID", bg."CustomizationGroupID")
      and gp."GroupBID" = greatest(ag."CustomizationGroupID", bg."CustomizationGroupID")
    where ag."CustomizationGroupID" <> bg."CustomizationGroupID"
      and not exists (
        select 1 from public."MenuCustomizationAllowedPair" ap
        where ap."OptionAID" = least(a."CustomizationOptionID", b."CustomizationOptionID")
          and ap."OptionBID" = greatest(a."CustomizationOptionID", b."CustomizationOptionID")
      )
  ) then raise exception 'That combination of options is not available' using errcode = '22023'; end if;

  select coalesce(sum(o."PriceDelta"), 0)::numeric(12,2),
         coalesce(jsonb_agg(jsonb_build_object(
           'option_id', o."CustomizationOptionID", 'group_name', g."Name", 'name', o."Name", 'price_delta', o."PriceDelta"
         ) order by g."SortOrder", o."SortOrder", o."CustomizationOptionID"), '[]'::jsonb)
    into v_price, v_options
  from public."MenuCustomizationOption" o
  join public."MenuCustomizationGroup" g on g."CustomizationGroupID" = o."CustomizationGroupID"
  where o."CustomizationOptionID" = any(v_ids);
  return jsonb_build_object('price_delta', v_price, 'selected_options', v_options);
end;
$$;

create or replace function public.esmiringkape_item_ingredient_requirements(
  p_menu_item_id bigint, p_selected_option_ids bigint[], p_quantity integer
) returns table("InventoryItemID" bigint, quantity_needed numeric)
language plpgsql stable security definer
set search_path = pg_catalog, public
as $$
declare
  v_multiplier numeric := 1;
  v_replaced bigint[];
begin
  select coalesce(exp(sum(ln(o."IngredientMultiplier"))), 1) into v_multiplier
  from public."MenuCustomizationOption" o where o."CustomizationOptionID" = any(coalesce(p_selected_option_ids, '{}'::bigint[]));
  select coalesce(array_agg(distinct oi."ReplacesInventoryItemID") filter (where oi."ReplacesInventoryItemID" is not null), '{}'::bigint[])
    into v_replaced
  from public."MenuOptionIngredient" oi
  where oi."CustomizationOptionID" = any(coalesce(p_selected_option_ids, '{}'::bigint[]));
  return query
    select requirements.inventory_item_id, sum(requirements.quantity)::numeric(14,3)
    from (
      select recipe."InventoryItemID" as inventory_item_id, recipe."QuantityRequired" * v_multiplier * p_quantity as quantity
      from public."MenuItemIngredient" recipe
      where recipe."MenuItemID" = p_menu_item_id and not (recipe."InventoryItemID" = any(v_replaced))
      union all
      select option_recipe."InventoryItemID", option_recipe."QuantityRequired" * case when option_recipe."ScaleWithSize" then v_multiplier else 1 end * p_quantity
      from public."MenuOptionIngredient" option_recipe
      where option_recipe."CustomizationOptionID" = any(coalesce(p_selected_option_ids, '{}'::bigint[]))
    ) requirements
    group by requirements.inventory_item_id;
end;
$$;

create or replace function public.esmiringkape_item_stock_available(p_menu_item_id bigint, p_selected_option_ids bigint[], p_quantity integer default 1)
returns boolean language plpgsql stable security definer
set search_path = pg_catalog, public
as $$
declare
  v_enforced boolean;
  v_has_recipe boolean;
begin
  select coalesce((select lower("SettingValue") = 'true' from public."ShopSetting" where "SettingKey" = 'inventory_enforced'), false) into v_enforced;
  if not v_enforced then return true; end if;
  -- A configured add-on recipe cannot stand in for the drink's base recipe.
  -- This preserves migration 003's rule that every sellable menu item needs a base recipe.
  select exists(select 1 from public."MenuItemIngredient" r where r."MenuItemID" = p_menu_item_id)
    into v_has_recipe;
  if not v_has_recipe then return false; end if;
  return not exists (
    select 1 from public.esmiringkape_item_ingredient_requirements(p_menu_item_id, p_selected_option_ids, p_quantity) needed
    left join public."InventoryItem" inventory on inventory."InventoryItemID" = needed."InventoryItemID" and inventory."IsActive"
    where inventory."InventoryItemID" is null or inventory."QuantityOnHand" < needed.quantity_needed
  );
end;
$$;

create or replace function public.esmiringkape_public_configuration_available(p_menu_item_id bigint, p_selected_option_ids bigint[])
returns boolean language plpgsql stable security definer
set search_path = pg_catalog, public
as $$
begin
  if not exists (select 1 from public."MenuItems" where "ItemID" = p_menu_item_id and "Available" is true) then return false; end if;
  perform public.esmiringkape_selected_customization(p_menu_item_id, p_selected_option_ids);
  return public.esmiringkape_item_stock_available(p_menu_item_id, p_selected_option_ids, 1);
exception when others then
  return false;
end;
$$;

create or replace function public.esmiringkape_snapshot_order_item()
returns trigger language plpgsql security definer
set search_path = pg_catalog, public
as $$
declare
  v_name text;
  v_price numeric(12,2);
  v_available boolean;
  v_options jsonb;
  v_recipe jsonb;
  v_config jsonb;
  v_ids bigint[];
begin
  select mi."ItemName", mi."Price"::numeric(12,2), mi."Available"
    into v_name, v_price, v_available from public."MenuItems" mi where mi."ItemID" = new."ItemID";
  if v_price is null then raise exception 'Menu item is unavailable or missing'; end if;
  if tg_op = 'INSERT' and v_available is distinct from true then raise exception 'Menu item is unavailable or missing'; end if;
  if new."Quantity" <= 0 then raise exception 'Quantity must be positive'; end if;

  if tg_op = 'INSERT' or new."SelectedOptionIDs" is distinct from old."SelectedOptionIDs" or new."ItemID" is distinct from old."ItemID" then
    v_ids := coalesce(new."SelectedOptionIDs", '{}'::bigint[]);
    v_config := public.esmiringkape_selected_customization(new."ItemID", v_ids);
    new."ItemNameSnapshot" := v_name;
    new."UnitPrice" := round(v_price + coalesce((v_config->>'price_delta')::numeric, 0), 2);
    if new."UnitPrice" < 0 then raise exception 'Customization price cannot be negative'; end if;
    if tg_op = 'INSERT' and not public.esmiringkape_item_stock_available(new."ItemID", v_ids, new."Quantity") then
      raise exception 'Sold out: this configuration cannot be prepared with current stock' using errcode = '23514';
    end if;
    new."OptionsSnapshot" := v_config->'selected_options';
    select coalesce(jsonb_agg(jsonb_build_object('inventory_item_id', needed."InventoryItemID", 'quantity', needed.quantity_needed)
      order by needed."InventoryItemID"), '[]'::jsonb) into v_recipe
    from public.esmiringkape_item_ingredient_requirements(new."ItemID", v_ids, 1) needed;
    new."OptionsSnapshot" := jsonb_build_object('selected_options', v_config->'selected_options', 'recipe_usage', v_recipe);
  else
    new."ItemNameSnapshot" := coalesce(old."ItemNameSnapshot", new."ItemNameSnapshot", v_name);
    -- Quantity edits and attempted direct price edits keep the original snapshots.
    new."UnitPrice" := coalesce(old."UnitPrice", new."UnitPrice", v_price);
    new."OptionsSnapshot" := coalesce(old."OptionsSnapshot", new."OptionsSnapshot", '[]'::jsonb);
  end if;
  new."LineTotal" := round(new."UnitPrice" * new."Quantity", 2);
  return new;
end;
$$;

drop trigger if exists order_item_price_snapshot on public."OrderItem";
create trigger order_item_price_snapshot
before insert or update of "ItemID", "Quantity", "UnitPrice", "SelectedOptionIDs"
on public."OrderItem" for each row execute function public.esmiringkape_snapshot_order_item();

-- Preserve existing item prices and initialize only the new recipe snapshot for legacy tickets.
update public."OrderItem" oi
set "OptionsSnapshot" = jsonb_build_object('selected_options', '[]'::jsonb, 'recipe_usage', coalesce((
  select jsonb_agg(jsonb_build_object('inventory_item_id', needed."InventoryItemID", 'quantity', needed.quantity_needed) order by needed."InventoryItemID")
  from public.esmiringkape_item_ingredient_requirements(oi."ItemID", '{}'::bigint[], 1) needed
), '[]'::jsonb))
where oi."OptionsSnapshot" = '[]'::jsonb;

-- Replace the existing deduction helper but keep its call site in confirm_cash_payment.
-- OrderItem.OptionsSnapshot is the immutable recipe snapshot captured at order submission.
create or replace function public.esmiringkape_deduct_order_stock(p_order_id bigint, p_employee_id bigint)
returns void language plpgsql security definer
set search_path = pg_catalog, public
as $$
declare
  v_item record;
  v_on_hand numeric(14,3);
  v_claimed bigint;
  v_enforced boolean;
begin
  insert into public."OrderStockDeduction" ("OrderID") values (p_order_id)
  on conflict do nothing returning "OrderID" into v_claimed;
  if v_claimed is null then return; end if;
  select coalesce((select lower("SettingValue") = 'true' from public."ShopSetting" where "SettingKey" = 'inventory_enforced'), false) into v_enforced;
  if v_enforced and exists (
    select 1 from public."OrderItem" oi
    where oi."OrderID" = p_order_id and coalesce(jsonb_array_length(oi."OptionsSnapshot"->'recipe_usage'), 0) = 0
  ) then raise exception 'Inventory recipe is missing for a drink on this ticket' using errcode = '23514'; end if;
  for v_item in
    select (recipe_snapshot.usage->>'inventory_item_id')::bigint as inventory_item_id,
      sum((recipe_snapshot.usage->>'quantity')::numeric * oi."Quantity")::numeric(14,3) as quantity_needed
    from public."OrderItem" oi
    cross join lateral jsonb_array_elements(coalesce(oi."OptionsSnapshot"->'recipe_usage', '[]'::jsonb)) as recipe_snapshot(usage)
    where oi."OrderID" = p_order_id
    group by (recipe_snapshot.usage->>'inventory_item_id')::bigint
    order by (recipe_snapshot.usage->>'inventory_item_id')::bigint
  loop
    select "QuantityOnHand" into v_on_hand from public."InventoryItem"
      where "InventoryItemID" = v_item.inventory_item_id and "IsActive" for update;
    if not found or v_on_hand < v_item.quantity_needed then
      raise exception 'Availability changed: insufficient stock for inventory item %', v_item.inventory_item_id using errcode = '23514';
    end if;
    update public."InventoryItem" set "QuantityOnHand" = "QuantityOnHand" - v_item.quantity_needed, "UpdatedAt" = clock_timestamp()
      where "InventoryItemID" = v_item.inventory_item_id;
    insert into public."InventoryMovement" ("InventoryItemID", "QuantityChange", "Reason", "MovementType", "OrderID", "EmployeeID")
      values (v_item.inventory_item_id, -v_item.quantity_needed, 'Sale for ticket #' || p_order_id, 'sale', p_order_id, p_employee_id);
  end loop;
end;
$$;

create or replace function public.esmiringkape_staff_order_json(p_order_id bigint)
returns jsonb language sql stable security definer
set search_path = pg_catalog, public
as $$
  select jsonb_build_object(
    'order_id', o."OrderID", 'order_number', o."OrderID"::text, 'ticket_number', o."OrderID"::text,
    'status', case when lower(o."Status") = 'pending' and lower(coalesce(p."PaymentStatus", 'unpaid')) <> 'paid' then 'Awaiting Payment'
      when lower(o."Status") = 'pending' then 'Waiting' else o."Status" end,
    'total', coalesce(o."TotalAmount", 0), 'subtotal', coalesce(o."Subtotal", o."TotalAmount", 0),
    'discount_total', coalesce(o."DiscountAmount", 0), 'tax_total', coalesce(o."TaxAmount", 0),
    'payment_status', coalesce(p."PaymentStatus", 'Unpaid'),
    'amount_paid', case when lower(coalesce(p."PaymentStatus", '')) in ('paid', 'partially refunded', 'refunded') then coalesce(p."AmountApplied", p."AmountPaid", 0) else 0 end,
    'refunded_amount', coalesce(p."RefundedAmount", 0),
    'net_amount', case when lower(coalesce(p."PaymentStatus", '')) in ('paid', 'partially refunded', 'refunded') then greatest(0, coalesce(p."AmountApplied", p."AmountPaid", 0) - coalesce(p."RefundedAmount", 0)) else 0 end,
    'amount_due', greatest(0, coalesce(o."TotalAmount", 0) - case when lower(coalesce(p."PaymentStatus", '')) in ('paid', 'partially refunded', 'refunded') then coalesce(p."AmountApplied", p."AmountPaid", 0) else 0 end),
    'payment_method', p."PaymentMethod", 'cash_tendered', p."CashTendered", 'change_given', p."ChangeGiven",
    'cashier', coalesce(cashier."FullName", staff."FullName"),
    'shop_name', coalesce((select s."SettingValue" from public."ShopSetting" s where s."SettingKey" = 'shop_name'), 'Esmiringkape'),
    'receipt_footer', (select s."SettingValue" from public."ShopSetting" s where s."SettingKey" = 'receipt_footer'),
    'created_at', o."OrderDate", 'guest_name', coalesce(o."PickupName", customer."FullName"),
    'order_type', coalesce(o."OrderType", 'guest'), 'service_type', o."ServiceType",
    'dining_table_id', o."DiningTableID", 'table_number', t."TableNumber", 'queue_entered_at', o."QueueEnteredAt",
    'items', coalesce((select jsonb_agg(jsonb_build_object(
      'item_id', oi."ItemID", 'item_name', coalesce(oi."ItemNameSnapshot", mi."ItemName", 'Item'),
      'quantity', oi."Quantity", 'unit_price', coalesce(oi."UnitPrice", mi."Price", 0),
      'line_total', coalesce(oi."LineTotal", oi."Quantity" * coalesce(oi."UnitPrice", mi."Price", 0)),
      'selected_options', coalesce(oi."OptionsSnapshot"->'selected_options', case when jsonb_typeof(oi."OptionsSnapshot") = 'array' then oi."OptionsSnapshot" else '[]'::jsonb end)
    ) order by oi."ItemID", oi.ctid) from public."OrderItem" oi
      left join public."MenuItems" mi on mi."ItemID" = oi."ItemID" where oi."OrderID" = o."OrderID"), '[]'::jsonb)
  )
  from public."Order" o
  left join public.customers customer on customer."customerID" = o."CustomerID"
  left join public."DiningTable" t on t."DiningTableID" = o."DiningTableID"
  left join public."Employee" staff on staff."EmployeeID" = o."EmployeeID"
  left join lateral (select payment.* from public."Payment" payment where payment."OrderID" = o."OrderID" order by payment."PaymentDate" desc nulls last limit 1) p on true
  left join public."Employee" cashier on cashier."EmployeeID" = p."VerifiedByEmployeeID"
  where o."OrderID" = p_order_id;
$$;

create or replace function public.esmiringkape_public_tables()
returns jsonb language sql stable security definer
set search_path = pg_catalog, public
as $$ select coalesce(jsonb_agg(jsonb_build_object('table_id', "DiningTableID", 'table_number', "TableNumber", 'public_token', "PublicToken") order by "TableNumber"), '[]'::jsonb)
from public."DiningTable" where "IsActive" $$;

create or replace function public.esmiringkape_public_menu(p_table_token uuid default null)
returns jsonb language plpgsql stable security definer
set search_path = pg_catalog, public
as $$
declare
  v_table jsonb := null;
  v_result jsonb;
begin
  if p_table_token is not null then
    select jsonb_build_object('table_id', t."DiningTableID", 'table_number', t."TableNumber", 'public_token', t."PublicToken")
      into v_table from public."DiningTable" t where t."PublicToken" = p_table_token and t."IsActive";
    if v_table is null then raise exception 'This table QR link is invalid or inactive. Please ask staff for help.' using errcode = 'P0002'; end if;
  end if;
  select jsonb_build_object(
    'table', v_table,
    'inventory_enforced', coalesce((select lower("SettingValue") = 'true' from public."ShopSetting" where "SettingKey" = 'inventory_enforced'), false),
    'categories', coalesce((select jsonb_agg(jsonb_build_object('CategoryID', c."CategoryID", 'CategoryName', c."CategoryName") order by c."CategoryName") from public."Categories" c), '[]'::jsonb),
    'items', coalesce((select jsonb_agg(jsonb_build_object(
      'ItemID', m."ItemID", 'ItemName', m."ItemName", 'Price', m."Price", 'CategoryID', m."CategoryID", 'Available', m."Available",
      'ImageURL', m."ImageURL", 'StockAvailable', public.esmiringkape_item_stock_available(m."ItemID", '{}'::bigint[], 1),
      'groups', coalesce((select jsonb_agg(jsonb_build_object(
        'group_id', g."CustomizationGroupID", 'name', g."Name", 'selection_type', g."SelectionType", 'required', g."IsRequired",
        'min_selections', g."MinSelections", 'max_selections', g."MaxSelections", 'sort_order', g."SortOrder",
        'options', coalesce((select jsonb_agg(jsonb_build_object(
          'option_id', o."CustomizationOptionID", 'name', o."Name", 'price_delta', o."PriceDelta", 'is_default', o."IsDefault",
          'available', public.esmiringkape_item_stock_available(m."ItemID", array[o."CustomizationOptionID"], 1), 'sort_order', o."SortOrder"
        ) order by o."SortOrder", o."CustomizationOptionID") from public."MenuCustomizationOption" o where o."CustomizationGroupID" = g."CustomizationGroupID" and o."IsActive"), '[]'::jsonb)
      ) order by g."SortOrder", g."CustomizationGroupID") from public."MenuCustomizationGroup" g where g."MenuItemID" = m."ItemID" and g."IsActive"), '[]'::jsonb)
    ) order by m."ItemName") from public."MenuItems" m), '[]'::jsonb)
  ) into v_result;
  return v_result;
end;
$$;

create or replace function public.esmiringkape_admin_list_menu_customizations()
returns jsonb language plpgsql stable security definer
set search_path = pg_catalog, public
as $$
begin
  if public.esmiringkape_staff_role() is distinct from 'admin' then raise exception 'Administrator access required' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('item_id', m."ItemID", 'groups', coalesce((
    select jsonb_agg(jsonb_build_object('name', g."Name", 'selection_type', g."SelectionType", 'required', g."IsRequired",
      'min_selections', g."MinSelections", 'max_selections', g."MaxSelections", 'options', coalesce((
        select jsonb_agg(jsonb_build_object('name', o."Name", 'price_delta', o."PriceDelta", 'is_default', o."IsDefault",
          'ingredient_multiplier', o."IngredientMultiplier", 'ingredients', coalesce((select jsonb_agg(jsonb_build_object(
            'inventory_item_id', r."InventoryItemID", 'quantity_required', r."QuantityRequired", 'replaces_inventory_item_id', r."ReplacesInventoryItemID", 'scale_with_size', r."ScaleWithSize"
          )) from public."MenuOptionIngredient" r where r."CustomizationOptionID" = o."CustomizationOptionID"), '[]'::jsonb))
        ) order by o."SortOrder", o."CustomizationOptionID") from public."MenuCustomizationOption" o where o."CustomizationGroupID" = g."CustomizationGroupID" and o."IsActive"
      ), '[]'::jsonb)) order by g."SortOrder", g."CustomizationGroupID") from public."MenuCustomizationGroup" g where g."MenuItemID" = m."ItemID" and g."IsActive"
  ), '[]'::jsonb), 'restricted_group_pairs', coalesce((
    select jsonb_agg(jsonb_build_object('group_a', ga."Name", 'group_b', gb."Name", 'allowed_pairs', coalesce((
      select jsonb_agg(jsonb_build_array(
        case when ao."CustomizationGroupID" = gp."GroupAID" then ao."Name" else bo."Name" end,
        case when ao."CustomizationGroupID" = gp."GroupBID" then ao."Name" else bo."Name" end
      )) from public."MenuCustomizationAllowedPair" ap
      join public."MenuCustomizationOption" ao on ao."CustomizationOptionID" = ap."OptionAID"
      join public."MenuCustomizationOption" bo on bo."CustomizationOptionID" = ap."OptionBID"
      where (ao."CustomizationGroupID" = gp."GroupAID" and bo."CustomizationGroupID" = gp."GroupBID")
         or (ao."CustomizationGroupID" = gp."GroupBID" and bo."CustomizationGroupID" = gp."GroupAID")
    ), '[]'::jsonb)) order by ga."SortOrder", gb."SortOrder")
    from public."MenuCustomizationGroupPair" gp
    join public."MenuCustomizationGroup" ga on ga."CustomizationGroupID" = gp."GroupAID"
    join public."MenuCustomizationGroup" gb on gb."CustomizationGroupID" = gp."GroupBID"
    where ga."MenuItemID" = m."ItemID"
  ), '[]'::jsonb)) order by m."ItemName") from public."MenuItems" m), '[]'::jsonb);
end;
$$;

create or replace function public.esmiringkape_admin_save_menu_customizations(p_menu_item_id bigint, p_configuration jsonb)
returns void language plpgsql security definer
set search_path = pg_catalog, public
as $$
declare
  v_group jsonb;
  v_option jsonb;
  v_ingredient jsonb;
  v_group_id bigint;
  v_option_id bigint;
  v_a_group bigint;
  v_b_group bigint;
  v_a_option bigint;
  v_b_option bigint;
begin
  if public.esmiringkape_staff_role() is distinct from 'admin' then raise exception 'Administrator access required' using errcode = '42501'; end if;
  if not exists (select 1 from public."MenuItems" where "ItemID" = p_menu_item_id) then raise exception 'Menu item not found'; end if;
  if jsonb_typeof(p_configuration->'groups') <> 'array' then raise exception 'Customization groups must be an array'; end if;
  delete from public."MenuCustomizationGroup" where "MenuItemID" = p_menu_item_id;
  for v_group in select value from jsonb_array_elements(p_configuration->'groups') loop
    insert into public."MenuCustomizationGroup" ("MenuItemID", "Name", "SelectionType", "IsRequired", "MinSelections", "MaxSelections", "SortOrder")
    values (p_menu_item_id, trim(v_group->>'name'), coalesce(v_group->>'selection_type', 'single'), coalesce((v_group->>'required')::boolean, false),
      coalesce((v_group->>'min_selections')::integer, case when coalesce((v_group->>'required')::boolean, false) then 1 else 0 end),
      coalesce((v_group->>'max_selections')::integer, 1), coalesce((v_group->>'sort_order')::integer, 0)) returning "CustomizationGroupID" into v_group_id;
    for v_option in select value from jsonb_array_elements(coalesce(v_group->'options', '[]'::jsonb)) loop
      insert into public."MenuCustomizationOption" ("CustomizationGroupID", "Name", "PriceDelta", "IngredientMultiplier", "IsDefault", "SortOrder")
      values (v_group_id, trim(v_option->>'name'), coalesce((v_option->>'price_delta')::numeric, 0), coalesce((v_option->>'ingredient_multiplier')::numeric, 1),
        coalesce((v_option->>'is_default')::boolean, false), coalesce((v_option->>'sort_order')::integer, 0)) returning "CustomizationOptionID" into v_option_id;
      for v_ingredient in select value from jsonb_array_elements(coalesce(v_option->'ingredients', '[]'::jsonb)) loop
        insert into public."MenuOptionIngredient" ("CustomizationOptionID", "InventoryItemID", "QuantityRequired", "ReplacesInventoryItemID", "ScaleWithSize")
        values (v_option_id, (v_ingredient->>'inventory_item_id')::bigint, (v_ingredient->>'quantity_required')::numeric,
          nullif(v_ingredient->>'replaces_inventory_item_id', '')::bigint, coalesce((v_ingredient->>'scale_with_size')::boolean, false));
      end loop;
    end loop;
  end loop;
  -- Optional group compatibility rules reference group and option names from this item's submitted config.
  for v_group in select value from jsonb_array_elements(coalesce(p_configuration->'restricted_group_pairs', '[]'::jsonb)) loop
    select "CustomizationGroupID" into v_a_group from public."MenuCustomizationGroup" where "MenuItemID" = p_menu_item_id and "Name" = v_group->>'group_a';
    select "CustomizationGroupID" into v_b_group from public."MenuCustomizationGroup" where "MenuItemID" = p_menu_item_id and "Name" = v_group->>'group_b';
    if v_a_group is null or v_b_group is null or v_a_group = v_b_group then raise exception 'Compatibility group names must refer to two different groups'; end if;
    insert into public."MenuCustomizationGroupPair" values (least(v_a_group, v_b_group), greatest(v_a_group, v_b_group));
    for v_option in select value from jsonb_array_elements(coalesce(v_group->'allowed_pairs', '[]'::jsonb)) loop
      select o."CustomizationOptionID" into v_a_option from public."MenuCustomizationOption" o join public."MenuCustomizationGroup" g using ("CustomizationGroupID") where g."CustomizationGroupID" = v_a_group and o."Name" = v_option->>0;
      select o."CustomizationOptionID" into v_b_option from public."MenuCustomizationOption" o join public."MenuCustomizationGroup" g using ("CustomizationGroupID") where g."CustomizationGroupID" = v_b_group and o."Name" = v_option->>1;
      if v_a_option is null or v_b_option is null then raise exception 'Allowed option pair refers to an unknown option'; end if;
      insert into public."MenuCustomizationAllowedPair" values (least(v_a_option, v_b_option), greatest(v_a_option, v_b_option));
    end loop;
  end loop;
end;
$$;

create or replace function public.esmiringkape_admin_list_dining_tables()
returns jsonb language plpgsql stable security definer
set search_path = pg_catalog, public
as $$
begin
  if public.esmiringkape_staff_role() is distinct from 'admin' then raise exception 'Administrator access required' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('table_id', t."DiningTableID", 'table_number', t."TableNumber", 'public_token', t."PublicToken", 'is_active', t."IsActive") order by t."TableNumber") from public."DiningTable" t), '[]'::jsonb);
end;
$$;

create or replace function public.esmiringkape_admin_save_dining_table(p_table_id bigint, p_table_number text, p_active boolean)
returns jsonb language plpgsql security definer
set search_path = pg_catalog, public
as $$
declare v_table public."DiningTable"%rowtype;
begin
  if public.esmiringkape_staff_role() is distinct from 'admin' then raise exception 'Administrator access required' using errcode = '42501'; end if;
  if nullif(trim(p_table_number), '') is null then raise exception 'Enter a table name or number'; end if;
  if p_table_id is null then
    insert into public."DiningTable" ("TableNumber", "IsActive") values (trim(p_table_number), coalesce(p_active, true)) returning * into v_table;
  else
    update public."DiningTable" set "TableNumber" = trim(p_table_number), "IsActive" = coalesce(p_active, false), "UpdatedAt" = clock_timestamp()
      where "DiningTableID" = p_table_id returning * into v_table;
  end if;
  if v_table."DiningTableID" is null then raise exception 'Dining table not found'; end if;
  return jsonb_build_object('table_id', v_table."DiningTableID", 'table_number', v_table."TableNumber", 'public_token', v_table."PublicToken", 'is_active', v_table."IsActive");
end;
$$;

create or replace function public.esmiringkape_quote_configured_sale(p_items jsonb, p_staff boolean default false)
returns jsonb language plpgsql stable security definer
set search_path = pg_catalog, public
as $$
declare
  v_line record;
  v_count integer := 0;
  v_subtotal numeric(12,2) := 0;
  v_discount_rate numeric(7,4);
  v_tax_rate numeric(7,4);
  v_discount numeric(12,2);
  v_tax numeric(12,2);
  v_config jsonb;
  v_item jsonb := '[]'::jsonb;
  v_item_name text;
  v_base numeric(12,2);
  v_unit numeric(12,2);
  v_stock_ok boolean;
  v_ids bigint[];
  v_enforced boolean;
begin
  if p_staff and coalesce(public.esmiringkape_staff_role(), '') not in ('admin', 'cashier') then raise exception 'Cashier access required' using errcode = '42501'; end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) not between 1 and 30 then raise exception 'Use 1 to 30 items per order' using errcode = '22023'; end if;
  for v_line in select * from jsonb_to_recordset(p_items) as x(item_id bigint, quantity integer, selected_option_ids bigint[]) loop
    if v_line.item_id is null then raise exception 'Choose a menu item'; end if;
    if v_line.quantity is null or v_line.quantity not between 1 and 99 then raise exception 'Quantity must be between 1 and 99'; end if;
    select "ItemName", "Price", "Available" into v_item_name, v_base, v_stock_ok from public."MenuItems" where "ItemID" = v_line.item_id;
    if v_base is null or not v_stock_ok then raise exception 'An item is unavailable. Refresh the menu and try again.' using errcode = '23514'; end if;
    v_ids := coalesce(v_line.selected_option_ids, '{}'::bigint[]);
    v_config := public.esmiringkape_selected_customization(v_line.item_id, v_ids);
    if not public.esmiringkape_item_stock_available(v_line.item_id, v_ids, v_line.quantity) then raise exception 'Availability changed: a selected drink cannot be prepared with current stock.' using errcode = '23514'; end if;
    v_unit := round(v_base + coalesce((v_config->>'price_delta')::numeric, 0), 2);
    if v_unit < 0 then raise exception 'Customization price cannot be negative' using errcode = '22023'; end if;
    v_subtotal := v_subtotal + v_unit * v_line.quantity;
    v_count := v_count + 1;
    v_item := v_item || jsonb_build_array(jsonb_build_object('item_id', v_line.item_id, 'item_name', v_item_name, 'quantity', v_line.quantity,
      'selected_option_ids', to_jsonb(v_ids), 'selected_options', v_config->'selected_options', 'unit_price', v_unit, 'line_total', round(v_unit * v_line.quantity, 2)));
  end loop;
  if v_count <> jsonb_array_length(p_items) then raise exception 'One or more order lines are invalid'; end if;
  select coalesce((select lower("SettingValue") = 'true' from public."ShopSetting" where "SettingKey" = 'inventory_enforced'), false) into v_enforced;
  if v_enforced and exists (
    select needed."InventoryItemID"
    from jsonb_to_recordset(p_items) as x(item_id bigint, quantity integer, selected_option_ids bigint[])
    cross join lateral public.esmiringkape_item_ingredient_requirements(x.item_id, coalesce(x.selected_option_ids, '{}'::bigint[]), x.quantity) needed
    group by needed."InventoryItemID"
    having sum(needed.quantity_needed) > coalesce((select inventory."QuantityOnHand" from public."InventoryItem" inventory
      where inventory."InventoryItemID" = needed."InventoryItemID" and inventory."IsActive"), 0)
  ) then raise exception 'Availability changed: there is not enough stock for this complete order.' using errcode = '23514'; end if;
  -- Match esmiringkape_calculate_order_totals for both guest and counter orders.
  select least(100, coalesce(sum("RatePercent"), 0)) into v_discount_rate from public."DiscountRule" where "IsActive";
  select coalesce(sum("RatePercent"), 0) into v_tax_rate from public."TaxRule" where "IsActive";
  v_discount := round(v_subtotal * v_discount_rate / 100, 2);
  v_tax := round((v_subtotal - v_discount) * v_tax_rate / 100, 2);
  return jsonb_build_object('subtotal', v_subtotal, 'discount_total', v_discount, 'tax_total', v_tax, 'total', v_subtotal - v_discount + v_tax, 'items', v_item);
end;
$$;

create or replace function public.esmiringkape_create_guest_order_v2(
  p_items jsonb, p_guest_token text, p_guest_name text default null,
  p_service_type text default 'takeaway', p_table_token uuid default null
) returns jsonb language plpgsql security definer
set search_path = pg_catalog, public
as $$
declare
  v_order_id bigint;
  v_employee bigint;
  v_table_id bigint;
  v_line record;
  v_quote jsonb;
  v_token_hash text;
begin
  if nullif(trim(p_guest_token), '') is null or length(p_guest_token) < 32 then raise exception 'A secure order tracking token is required'; end if;
  v_token_hash := md5(p_guest_token);
  perform pg_advisory_xact_lock(hashtextextended(v_token_hash, 0));
  select "OrderID" into v_order_id from public."GuestOrderAccess" where "TokenHash" = v_token_hash;
  if v_order_id is not null then return public.esmiringkape_guest_order_json(v_order_id); end if;

  if p_service_type is null or p_service_type not in ('dine_in', 'takeaway') then raise exception 'Choose dine-in or takeaway'; end if;
  if p_service_type = 'dine_in' then
    if p_table_token is null then raise exception 'Choose an active table for dine-in'; end if;
    select "DiningTableID" into v_table_id from public."DiningTable" where "PublicToken" = p_table_token and "IsActive";
    if v_table_id is null then raise exception 'This table is no longer active. Choose another table or switch to takeaway.' using errcode = '23514'; end if;
  elsif p_service_type = 'takeaway' and p_table_token is not null then raise exception 'Takeaway orders cannot be assigned to a table';
  end if;
  v_quote := public.esmiringkape_quote_configured_sale(p_items, false);
  insert into public."Order" ("CustomerID", "OrderDate", "Status", "EmployeeID", "PickupName", "OrderType", "ServiceType", "DiningTableID", "Subtotal", "TotalAmount")
  values (null, clock_timestamp(), 'Pending', null, nullif(trim(p_guest_name), ''), 'guest', p_service_type, v_table_id,
    (v_quote->>'subtotal')::numeric, (v_quote->>'total')::numeric) returning "OrderID" into v_order_id;
  for v_line in select * from jsonb_to_recordset(p_items) as x(item_id bigint, quantity integer, selected_option_ids bigint[]) loop
    insert into public."OrderItem" ("OrderID", "ItemID", "Quantity", "SelectedOptionIDs")
    values (v_order_id, v_line.item_id, v_line.quantity, coalesce(v_line.selected_option_ids, '{}'::bigint[]));
  end loop;
  perform public.esmiringkape_calculate_order_totals(v_order_id);
  insert into public."GuestOrderAccess" ("OrderID", "TokenHash") values (v_order_id, v_token_hash);
  return public.esmiringkape_guest_order_json(v_order_id);
end;
$$;

create or replace function public.esmiringkape_guest_order_json(p_order_id bigint)
returns jsonb language sql stable security definer
set search_path = pg_catalog, public
as $$
  select jsonb_build_object(
    'order_id', o."OrderID", 'order_number', o."OrderID"::text, 'ticket_number', o."OrderID"::text,
    'status', case when lower(o."Status") = 'pending' and lower(coalesce(p."PaymentStatus", 'unpaid')) <> 'paid' then 'Awaiting Payment'
      when lower(o."Status") = 'pending' then 'Waiting' else o."Status" end,
    'total', coalesce(o."TotalAmount", 0), 'subtotal', coalesce(o."Subtotal", o."TotalAmount", 0),
    'discount_total', coalesce(o."DiscountAmount", 0), 'tax_total', coalesce(o."TaxAmount", 0),
    'payment_status', coalesce(p."PaymentStatus", 'Unpaid'),
    'created_at', o."OrderDate", 'guest_name', o."PickupName", 'order_type', 'guest',
    'service_type', o."ServiceType", 'table_number', t."TableNumber",
    'items', coalesce((select jsonb_agg(jsonb_build_object(
      'item_id', oi."ItemID", 'item_name', coalesce(oi."ItemNameSnapshot", mi."ItemName", 'Item'),
      'quantity', oi."Quantity", 'unit_price', coalesce(oi."UnitPrice", mi."Price", 0),
      'line_total', coalesce(oi."LineTotal", oi."Quantity" * coalesce(oi."UnitPrice", mi."Price", 0)),
      'selected_options', coalesce(oi."OptionsSnapshot"->'selected_options', case when jsonb_typeof(oi."OptionsSnapshot") = 'array' then oi."OptionsSnapshot" else '[]'::jsonb end)
    ) order by oi."ItemID", oi.ctid) from public."OrderItem" oi
      left join public."MenuItems" mi on mi."ItemID" = oi."ItemID" where oi."OrderID" = o."OrderID"), '[]'::jsonb)
  )
  from public."Order" o
  left join public."DiningTable" t on t."DiningTableID" = o."DiningTableID"
  left join lateral (select payment."PaymentStatus" from public."Payment" payment where payment."OrderID" = o."OrderID" order by payment."PaymentDate" desc nulls last limit 1) p on true
  where o."OrderID" = p_order_id;
$$;

create or replace function public.esmiringkape_track_guest_order_v2(p_guest_token text)
returns jsonb language sql stable security definer
set search_path = pg_catalog, public
as $$
  select public.esmiringkape_guest_order_json(a."OrderID") from public."GuestOrderAccess" a
  where a."TokenHash" = md5(coalesce(p_guest_token, ''));
$$;

create or replace function public.esmiringkape_quote_counter_sale_v2(p_items jsonb)
returns jsonb language sql stable security definer
set search_path = pg_catalog, public
as $$ select public.esmiringkape_quote_configured_sale(p_items, true) $$;

create or replace function public.esmiringkape_complete_counter_sale_v2(
  p_idempotency_key uuid, p_items jsonb, p_customer_id bigint, p_pickup_name text,
  p_cash_tendered numeric, p_service_type text, p_dining_table_id bigint default null
) returns jsonb language plpgsql security definer
set search_path = pg_catalog, public
as $$
declare
  v_employee_id bigint;
  v_order_id bigint;
  v_table_id bigint;
  v_quote jsonb;
  v_line record;
begin
  if coalesce(public.esmiringkape_staff_role(), '') not in ('admin', 'cashier') then raise exception 'Cashier access required' using errcode = '42501'; end if;
  if p_idempotency_key is null then raise exception 'Idempotency key required'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text, 0));
  select "OrderID" into v_order_id from public."SaleIdempotency" where "IdempotencyKey" = p_idempotency_key;
  if v_order_id is not null then return public.esmiringkape_staff_order_json(v_order_id); end if;

  if p_service_type is null or p_service_type not in ('dine_in', 'takeaway') then raise exception 'Choose dine-in or takeaway'; end if;
  if p_service_type = 'dine_in' then
    select "DiningTableID" into v_table_id from public."DiningTable" where "DiningTableID" = p_dining_table_id and "IsActive";
    if v_table_id is null then raise exception 'Choose an active table for dine-in'; end if;
  elsif p_service_type = 'takeaway' and p_dining_table_id is not null then raise exception 'Takeaway orders cannot be assigned to a table';
  end if;
  if p_customer_id is not null and not exists(select 1 from public.customers where "customerID" = p_customer_id) then raise exception 'Customer not found'; end if;
  v_quote := public.esmiringkape_quote_configured_sale(p_items, true);
  if p_cash_tendered is null or p_cash_tendered < (v_quote->>'total')::numeric then raise exception 'Cash received must cover %', v_quote->>'total'; end if;
  v_employee_id := public.esmiringkape_current_employee_id();
  insert into public."Order" ("CustomerID", "OrderDate", "Status", "EmployeeID", "PickupName", "OrderType", "ServiceType", "DiningTableID", "Subtotal", "TotalAmount")
  values (p_customer_id, clock_timestamp(), 'Pending', v_employee_id, nullif(trim(p_pickup_name), ''), 'counter', p_service_type, v_table_id,
    (v_quote->>'subtotal')::numeric, (v_quote->>'total')::numeric) returning "OrderID" into v_order_id;
  for v_line in select * from jsonb_to_recordset(p_items) as x(item_id bigint, quantity integer, selected_option_ids bigint[]) loop
    insert into public."OrderItem" ("OrderID", "ItemID", "Quantity", "SelectedOptionIDs")
    values (v_order_id, v_line.item_id, v_line.quantity, coalesce(v_line.selected_option_ids, '{}'::bigint[]));
  end loop;
  perform public.esmiringkape_calculate_order_totals(v_order_id);
  perform public.esmiringkape_confirm_cash_payment(v_order_id, p_cash_tendered);
  insert into public."SaleIdempotency" ("IdempotencyKey", "OrderID") values (p_idempotency_key, v_order_id);
  return public.esmiringkape_staff_order_json(v_order_id);
end;
$$;

-- Admin movement history feeds the existing screen and remains separate from refunds.
create or replace function public.esmiringkape_admin_inventory_movements(p_from date, p_to date)
returns jsonb language plpgsql stable security definer
set search_path = pg_catalog, public
as $$
begin
  if public.esmiringkape_staff_role() is distinct from 'admin' then raise exception 'Administrator access required' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('movement_id', m."InventoryMovementID", 'inventory_item_id', m."InventoryItemID", 'name', i."Name",
    'quantity_change', m."QuantityChange", 'reason', m."Reason", 'movement_type', m."MovementType", 'order_id', m."OrderID", 'employee', e."FullName", 'created_at', m."CreatedAt")
    order by m."CreatedAt" desc) from public."InventoryMovement" m join public."InventoryItem" i using ("InventoryItemID")
    left join public."Employee" e on e."EmployeeID" = m."EmployeeID"
    where (m."CreatedAt" at time zone 'Asia/Manila')::date between p_from and p_to), '[]'::jsonb);
end;
$$;

